import json

# Input sequence (space-separated tokens)
SEQUENCE = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"

CLOSER_TO_OPENER = {")": "(", "]": "[", "}": "{", ">": "<"}
OPENER_TO_CLOSER = {v: k for k, v in CLOSER_TO_OPENER.items()}

def complete_sequence(text):
    stack = []
    tokens = text.split()
    for tok in tokens:
        if tok in OPENER_TO_CLOSER:
            stack.append(tok)
        elif tok in CLOSER_TO_OPENER:
            if stack and stack[-1] == CLOSER_TO_OPENER[tok]:
                stack.pop()
            else:
                return None, {"tokens": len(tokens), "error": "mismatched closer", "at": tok}
        else:
            return None, {"tokens": len(tokens), "error": "unknown token", "at": tok}
    closers = [OPENER_TO_CLOSER[t] for t in reversed(stack)]
    evidence = {
        "tokens": len(tokens),
        "unclosed_openers_bottom_to_top": stack,
        "max_stack_depth_at_end": len(stack),
    }
    return closers, evidence

closers, info = complete_sequence(SEQUENCE)

if closers is None:
    result = {"final_answer": "UNSUPPORTED", "evidence": info}
else:
    result = {"final_answer": " ".join(closers), "evidence": info}

print(json.dumps(result, separators=(",", ":")))
